def _sem_name(arm: ASTNode, parent_cname: str, seen: dict[str, int]) -> str:
    """Derive a semantic class name for an alternation arm."""
    # Unwrap single-element SequenceNode → treat as its inner node
    if isinstance(arm, SequenceNode) and len(arm.nodes) == 1:
        arm = arm.nodes[0]

    # Case 1: bare RuleRefNode  →  {RefClass}{ParentClass}
    if isinstance(arm, RuleRefNode):
        return to_class_name(arm.name) + parent_cname

    if isinstance(arm, SequenceNode):
        nodes = arm.nodes

        # Case 2: first purely-alpha LiteralNode (keyword arm)
        for node in nodes:
            if isinstance(node, LiteralNode):
                val = node.value.strip("\"'")
                if val.isalpha():
                    return parent_cname + val.title()

        # Case 3: inline-literal-group — first node is AlternativeNode of all LiteralNodes
        if nodes and isinstance(nodes[0], AlternativeNode):
            if all(isinstance(a, LiteralNode) for a in nodes[0].alternatives):
                return parent_cname + "Literal"

        # Case 4: first non-ws RuleRefNode fallback
        _WS = {"ws", "wsp", "whitespace", "sp", " "}
        for node in nodes:
            if isinstance(node, RuleRefNode) and node.name not in _WS:
                return parent_cname + to_class_name(node.name)

    # Final fallback (should not be reached for well-formed grammars)
    return parent_cname + "Arm"


def _dedup_name(candidate: str, seen: dict[str, int]) -> str:
    """Return candidate, or candidate+N for N>=2 if already used; update seen."""
    count = seen.get(candidate, 0)
    seen[candidate] = count + 1
    return candidate if count == 0 else f"{candidate}{count + 1}"


def _collect(defs: list[_ClassDef], rules: dict[str, RuleNode]) -> None:
    """Populate defs in rule.order, before topological sort."""
    non_terminals = sorted(
        (r for r in rules.values() if not r.rule_is_terminal),
        key=lambda r: r.order,
    )

    for rule in non_terminals:
        cname = to_class_name(rule.name)
        body = rule.alternatives

        if isinstance(body, AlternativeNode) and len(body.alternatives) > 1:
            # Abstract base
            defs.append(_ClassDef(cname, "BaseModel", ["    pass"]))
            # Typed subclasses — track used names for collision dedup
            seen_names: dict[str, int] = {}
            for i, alt in enumerate(body.alternatives):
                if isinstance(alt, RuleRefNode):
                    sub = f"{to_class_name(alt.name)}{cname}"
                    seen_names[sub] = seen_names.get(sub, 0) + 1
                    if alt.target is None or alt.target.rule_is_terminal:
                        defs.append(_ClassDef(sub, cname, ["    value: str"]))
                    else:
                        field = to_field_name(alt.name)
                        target_cls = to_class_name(alt.target.name)
                        defs.append(_ClassDef(sub, cname, [f"    {field}: {target_cls}"]))
                elif isinstance(alt, SequenceNode):
                    name = _dedup_name(_sem_name(alt, cname, seen_names), seen_names)
                    defs.append(_ClassDef(name, cname, _sequence_body(alt)))
                else:
                    name = _dedup_name(_sem_name(alt, cname, seen_names), seen_names)
                    typ = _node_to_type(alt) or "str"
                    defs.append(_ClassDef(name, cname, [f"    value: {typ}"]))
